Edit `build.gradle`:
```groovy
plugins {
    id 'java'
}

repositories {
    mavenCentral()
}

dependencies {
    testImplementation 'com.intuit.karate:karate-junit5:1.4.0'
    testImplementation 'org.junit.jupiter:junit-jupiter:5.9.2'
}

// Ensure Karate output directory exists
task createKarateOutputDirs {
    doLast {
        mkdir("build/karate-reports")
    }
}
test.dependsOn createKarateOutputDirs

// Configure test task
 test {
     useJUnitPlatform()
     systemProperty "karate.env", System.properties.getProperty("karate.env")
     outputs.upToDateWhen { false }
     testLogging.showStandardStreams = true
 }

// Ensure feature files are copied to classpath
sourceSets {
    test {
        resources {
            srcDir file('src/test/java')
            exclude '**/*.java'
        }
    }
}
```

Create `src/test/java/com/example/UsersTest.java`:
```java
package com.example;

import com.intuit.karate.junit5.Karate;

class UsersTest {

    @Karate.Test
