content.explanation:
**Mastering Karate's Configuration System:**

**1. Environment-Specific Configuration**

```javascript
// karate-config.js
function fn() {
    var env = karate.env || 'dev';
    karate.log('Using environment:', env);

    var config = {
        env: env,
        timeout: 10000
    };

    if (env == 'dev') {
        config.baseUrl = 'https://dev-api.example.com';
        config.authToken = 'dev-token';
        config.dbConfig = {
            url: 'jdbc:mysql://dev-db:3306/test',
            user: 'devuser',
            password: 'devpass'
        };
    } else if (env == 'staging') {
        config.baseUrl = 'https://staging-api.example.com';
        config.authToken = karate.properties['staging.token'];
        config.dbConfig = {
            url: 'jdbc:mysql://staging-db:3306/test',
            user: 'staginguser',
            password: karate.properties['db.password']
        };
    } else if (env == 'prod') {
        config.baseUrl = 'https://api.example.com';
        config.authToken = karate.properties['prod.token'];
        config.dbConfig = {
            url: 'jdbc:mysql://prod-db:3306/test',
            user: 'produser',
            password: karate.properties['db.password']
        };
    }

    // Global HTTP settings
    karate.configure('connectTimeout', 5000);
    karate.configure('readTimeout', config.timeout);
    karate.configure('ssl', true);
    karate.configure('logPrettyRequest', true);
    karate.configure('logPrettyResponse', true);

    return config;
}
```

**2. Multiple Config Files**

```
src/test/resources/
├── karate-config.js              # Default (loaded first)
├── karate-config-dev.js          # Loaded when env=dev
├── karate-config-staging.js      # Loaded when env=staging
└── karate-config-prod.js         # Loaded when env=prod
```

**3. karate-config-dev.js Example**

```javascript
function fn() {
    var config = {
        baseUrl: 'https://dev-api.example.com',
        dbUrl: 'jdbc:mysql://dev-db:3306/test',
        timeout: 15000,
        retryCount: 3
    };

    // Configure logging
    karate.configure('logPrettyRequest', true);
    karate.configure('logPrettyResponse', true);

    // Configure headers
    karate.configure('headers', {
        'X-Environment': 'dev',
        'X-API-Version': '2.0'
    });

    return config;
}
```

**4. Dynamic Configuration**

```javascript
function fn() {
    var config = {
        baseUrl: 'https://api.example.com',
        timestamp: java.lang.System.currentTimeMillis()
    };

    // Generate dynamic values
    config.randomEmail = function() {
        return 'user_' + config.timestamp + '@test.com';
    };

    // Conditional logic
    config.getAuthToken = function() {
        if (karate.env == 'prod') {
            return karate.properties['prod.token'];
        } else {
            return 'test-token';
        }
    };

    return config;
}
```

**5. Using Configuration in Tests**

```gherkin
Feature: Using configuration

Scenario: Access config values
    * print 'Environment:', env
    * print 'Base URL:', baseUrl
    * print 'Timeout:', timeout

    # Use config functions
    * def email = randomEmail()
    * def token = getAuthToken()

    Given url baseUrl + '/users'
    And header Authorization = 'Bearer ' + token
    And request { email: '#(email)' }
    When method post
    Then status 201
```

**6. Configuration Hooks**

```javascript
function fn() {
    var config = {
        baseUrl: 'https://api.example.com'
    };

    // Before all tests
    karate.once('beforeAll', function() {
        karate.log('Starting test suite');
        // Setup test data
    });

    // After all tests
    karate.once('afterAll', function() {
        karate.log('Test suite complete');
        // Clean up test data
    });

    return config;
}
```

**7. Configuration Best Practices**

✅ **Use environment-specific files** – Separate configs per environment
✅ **Never hardcode secrets** – Use karate.properties or environment variables
✅ **Document configuration** – Comment complex config
✅ **Keep it DRY** – Use functions for repeated logic
✅ **Test configuration** – Verify config loads correctly
✅ **Version control configs** – Track changes to test setup

**Generating Realistic Test Data Programmatically:**

Dynamic data generation is essential for creating robust, repeatable tests that don't collide with each other. Karate provides multiple ways to generate test data on the fly using JavaScript functions, external libraries, and file generation.

**1. JavaScript Data Generators**

Create reusable JavaScript functions to generate realistic test data:

```javascript
// data-generators.js
function randomEmail() {
    var timestamp = new Date().getTime();
    return 'user_' + timestamp + '@test.com';
}

function randomName() {
    var firstNames = ['John', 'Jane', 'Bob', 'Alice', 'Charlie'];
    var lastNames = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'];
    var firstName = firstNames[Math.floor(Math.random() * firstNames.length)];
    var lastName = lastNames[Math.floor(Math.random() * lastNames.length)];
    return firstName + ' ' + lastName;
}

function randomAge() {
    return Math.floor(Math.random() * 50) + 18;
}

function randomPhone() {
    return '(' + Math.floor(Math.random() * 900 + 100) + ') ' +
           Math.floor(Math.random() * 900 + 100) + '-' +
           Math.floor(Math.random() * 9000 + 1000);
}

function randomUser() {
    return {
        name: randomName(),
        email: randomEmail(),
        age: randomAge(),
        phone: randomPhone(),
        registered: new Date().toISOString()
    };
}

function randomUsers(count) {
    var users = [];
    for (var i = 0; i < count; i++) {
        users.push(randomUser());
    }
    return users;
}
```

**2. Using Data Generators in Tests**

```gherkin
Feature: Dynamic data generation

Background:
    * def gen = call read('data-generators.js')
    * url baseUrl + '/users'

Scenario: Create user with random data
    * def user = gen.randomUser()
