**5. SQL Data Generation**

Generate SQL statements for database setup:

```javascript
// sql-generator.js
function generateInsertSQL(table, data) {
    var columns = Object.keys(data).join(', ');
    var values = Object.values(data).map(function(v) {
        return typeof v === 'string' ? "'" + v.replace(/'/g, "''") + "'" : v;
    }).join(', ');
    return 'INSERT INTO ' + table + ' (' + columns + ') VALUES (' + values + ');';
}

function generateBatchInsertSQL(table, rows) {
    var sql = [];
    for (var i = 0; i < rows.length; i++) {
        sql.push(generateInsertSQL(table, rows[i]));
    }
    return sql.join('\n');
}

function generateTestDataSQL() {
    var users = [
        { name: 'John', email: 'john@test.com', age: 30 },
        { name: 'Jane', email: 'jane@test.com', age: 25 },
        { name: 'Bob', email: 'bob@test.com', age: 35 }
    ];
    return generateBatchInsertSQL('users', users);
}
```

**6. UUID Generation**

Generate unique identifiers:

```javascript
// uuid-generator.js
function uuid() {
    var dt = new Date().getTime();
    var uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        var r = (dt + Math.random() * 16) % 16 | 0;
        dt = Math.floor(dt / 16);
        return (c == 'x' ? r : (r & 0x3 | 0x8)).toString(16);
    });
    return uuid;
}

function shortId() {
    return Math.random().toString(36).substring(2, 10);
}
```

```gherkin
* def uuidGen = call read('uuid-generator.js')
* def orderId = uuidGen.uuid()
* def transactionId = uuidGen.shortId()
```

**7. Date and Time Generation**

Generate dates for testing:

```javascript
// date-generator.js
function today() {
    var d = new Date();
    return d.toISOString().split('T')[0];
}

function futureDays(days) {
    var d = new Date();
    d.setDate(d.getDate() + days);
    return d.toISOString().split('T')[0];
}

function pastDays(days) {
    var d = new Date();
    d.setDate(d.getDate() - days);
    return d.toISOString().split('T')[0];
}

function timestamp() {
    return new Date().toISOString();
}

function randomDate(start, end) {
    return new Date(start.getTime() + Math.random() * (end.getTime() - start.getTime()));
}
```

**8. Conditional Data Generation**

Generate data based on conditions:

```javascript
// conditional-generator.js
function getUserByRole(role) {
    var users = {
        admin: { name: 'Admin User', permissions: ['read', 'write', 'delete'] },
        manager: { name: 'Manager User', permissions: ['read', 'write'] },
        user: { name: 'Regular User', permissions: ['read'] }
    };
    return users[role] || users.user;
}

function getPaymentDetails(method) {
    var payments = {
        credit: { type: 'credit_card', processor: 'visa' },
        paypal: { type: 'paypal', email: 'user@paypal.com' },
        crypto: { type: 'crypto', currency: 'bitcoin' }
    };
    return payments[method];
}
```

**9. Data Generation with External Files**

Read and transform external data:

```javascript
// data-transformer.js
function loadAndTransform() {
    var rawData = read('classpath:data/template.json');
    var timestamp = new Date().getTime();

    return {
        id: timestamp,
        name: rawData.name + ' ' + timestamp,
        email: 'user_' + timestamp + '@test.com',
        metadata: {
            created: new Date().toISOString(),
            source: 'generated'
        }
    };
}
```

**10. Dynamic Data Best Practices**

✅ **Use unique data** – Prevent test collisions with timestamps or UUIDs
✅ **Realistic data** – Match production patterns for better test coverage
✅ **Boundary values** – Test edge cases (min, max, null, empty)
✅ **Clean up** – Delete generated test data after test execution
✅ **Reproducible** – Use seeds for random data to reproduce failures
