public class FluentWaitExample {
    public WebElement waitForElementToBeStable(By locator) {
        FluentWait<WebDriver> wait = new FluentWait<WebDriver>(driver)
            .withTimeout(Duration.ofSeconds(10))
            .pollingEvery(Duration.ofMillis(200))
            .ignoring(NoSuchElementException.class)
            .ignoring(StaleElementReferenceException.class)
            .withMessage("Element never became stable: " + locator);

        return wait.until(driver -> {
            WebElement element = driver.findElement(locator);
            if (element.isDisplayed() && element.isEnabled()) {
                // Check if element position is stable (not animating)
                Point location1 = element.getLocation();
                Thread.sleep(100);
                Point location2 = element.getLocation();

                return location1.equals(location2) ? element : null;
            }
            return null;
        });
    }
}
