        wait.until(driver -> {
            JavascriptExecutor js = (JavascriptExecutor) driver;

            // Check jQuery
            Boolean jQueryComplete = (Boolean) js.executeScript(
                "return typeof jQuery === 'undefined' ? true : jQuery.active == 0"
            );

            // Check Angular
            Boolean angularComplete = (Boolean) js.executeScript(
                "return typeof angular === 'undefined' ? true : " +
                "angular.element(document).injector().get('$http').pendingRequests.length == 0"
            );

            // Check XMLHttpRequest
            Boolean xhrComplete = (Boolean) js.executeScript(
                "return window.XMLHttpRequest ? " +
                "window.XMLHttpRequest.active == 0 : true"
            );

            return jQueryComplete && angularComplete && xhrComplete;
        });
    }

    public void waitForElementAfterAjax(By locator) {
        waitForAjax();
        wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
