        driver.findElement(By.id("refreshTable")).click();

        // Wait for HTML to change
        wait.until(driver -> {
            String currentHtml = driver.findElement(tableLocator).getAttribute("outerHTML");
            return !currentHtml.equals(initialHtml);
        });
    }
}
