**2. Handling Table Sorting**

```java
public class SortableTableHandler {
    private WebDriver driver;
    private WebDriverWait wait;

    public SortableTableHandler(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
    }

    public List<String> getColumnData(int columnIndex) {
        return driver.findElements(By.cssSelector("table tbody tr td:nth-child(" + columnIndex + ")"))
            .stream()
            .map(WebElement::getText)
            .collect(Collectors.toList());
    }

    public void sortByColumn(String columnName) {
        // Get initial data
        List<String> beforeSort = getColumnData(getColumnIndex(columnName));

        // Click sort header
        By headerLocator = By.xpath("//th[contains(text(), '" + columnName + "')]");
        driver.findElement(headerLocator).click();

        // Wait for data to change
        wait.until(driver -> {
            List<String> afterSort = getColumnData(getColumnIndex(columnName));
            return !afterSort.equals(beforeSort);
        });

        // Add small delay for animation
        Thread.sleep(500);
    }

    private int getColumnIndex(String columnName) {
        List<WebElement> headers = driver.findElements(By.cssSelector("table thead th"));
        for (int i = 0; i < headers.size(); i++) {
            if (headers.get(i).getText().contains(columnName)) {
                return i + 1; // nth-child is 1-based
            }
        }
        throw new AssertionError("Column not found: " + columnName);
    }
}
```

**3. Handling Table Pagination**

```java
public class PaginatedTableHandler {
    private WebDriver driver;
    private WebDriverWait wait;

    public PaginatedTableHandler(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
    }

    public void goToPage(int pageNumber) {
        // Store first row data to detect change
        String firstRowBefore = getFirstRowData();

        // Click page button
        By pageButton = By.xpath("//div[@class='pagination']//a[text()='" + pageNumber + "']");
        driver.findElement(pageButton).click();

        // Wait for table to update
        wait.until(driver -> {
            String firstRowAfter = getFirstRowData();
            return !firstRowAfter.equals(firstRowBefore);
        });
    }

    private String getFirstRowData() {
        List<WebElement> cells = driver.findElements(
            By.cssSelector("table tbody tr:first-child td")
        );
        return cells.stream()
            .map(WebElement::getText)
            .collect(Collectors.joining("|"));
    }

    public int getTotalPages() {
        List<WebElement> pageLinks = driver.findElements(
            By.cssSelector(".pagination a:not(.next):not(.prev)")
        );
        return pageLinks.size();
    }
}
```

**4. Handling Table Filtering**

```java
public class FilterableTableHandler {
    private WebDriver driver;
    private WebDriverWait wait;
    private Map<String, List<String>> dataBeforeFilter;

    public FilterableTableHandler(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
    }

    public void applyFilter(String column, String value) {
        // Capture current data
        dataBeforeFilter = captureTableData();

        // Apply filter
        By filterInput = By.xpath("//th[contains(text(), '" + column + "')]/following::input[1]");
        WebElement input = driver.findElement(filterInput);
        input.clear();
        input.sendKeys(value);

        // Trigger filter (may need Enter or wait for debounce)
        input.sendKeys(Keys.ENTER);

        // Wait for results
        waitForFilterResults();
    }

    private void waitForFilterResults() {
        wait.until(driver -> {
            Map<String, List<String>> currentData = captureTableData();
            return !currentData.equals(dataBeforeFilter);
        });

        // Wait for loading indicator if present
        try {
            wait.until(ExpectedConditions.invisibilityOfElementLocated(
                By.className("filter-loading")
            ));
        } catch (TimeoutException e) {
            // No loading indicator
        }
    }

    private Map<String, List<String>> captureTableData() {
        Map<String, List<String>> data = new HashMap<>();
        List<WebElement> headers = driver.findElements(By.cssSelector("table thead th"));
        List<WebElement> rows = driver.findElements(By.cssSelector("table tbody tr"));

        for (int i = 0; i < headers.size(); i++) {
            String header = headers.get(i).getText();
            List<String> columnData = new ArrayList<>();

            for (WebElement row : rows) {
                List<WebElement> cells = row.findElements(By.tagName("td"));
                if (cells.size() > i) {
                    columnData.add(cells.get(i).getText());
                }
            }
            data.put(header, columnData);
        }
        return data;
    }
}
```

