public class SyncUtils {
    private WebDriver driver;

    public SyncUtils(WebDriver driver) {
        this.driver = driver;
    }

    // Retry operation with exponential backoff
    public <T> T retryOnFailure(Supplier<T> operation, int maxRetries) {
        int retryCount = 0;
        int delay = 1000; // Start with 1 second

        while (retryCount < maxRetries) {
            try {
                return operation.get();
            } catch (Exception e) {
                retryCount++;
                if (retryCount == maxRetries) {
                    throw new AssertionError("Operation failed after " + maxRetries + " retries", e);
                }
                try {
                    Thread.sleep(delay);
                    delay *= 2; // Double delay each time
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
        return null;
    }

    // Wait for JavaScript condition
    public void waitForJavaScriptCondition(String script, int timeoutSeconds) {
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(timeoutSeconds));
        wait.until(driver -> (Boolean) ((JavascriptExecutor) driver).executeScript(script));
    }
}
