public class GridLoadTest {

    @Test
    public void testGridCapacity() throws InterruptedException {
        int targetConcurrentSessions = 100;
        CountDownLatch latch = new CountDownLatch(targetConcurrentSessions);
        AtomicInteger successCount = new AtomicInteger();

        for (int i = 0; i < targetConcurrentSessions; i++) {
            new Thread(() -> {
                try {
                    RemoteWebDriver driver = new RemoteWebDriver(
                        new URL("http://hub:4444"),
                        new ChromeOptions()
                    );
                    driver.get("https://example.com");
                    driver.quit();
                    successCount.incrementAndGet();
                } catch (Exception e) {
                    System.err.println("Session failed: " + e.getMessage());
                } finally {
                    latch.countDown();
                }
            }).start();
        }

        latch.await(5, TimeUnit.MINUTES);
        double successRate = (successCount.get() * 100.0) / targetConcurrentSessions;
        System.out.println("Success rate: " + successRate + "%");
        assertTrue(successRate > 95, "Grid should handle 95%+ of sessions");
    }

    private void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
