public class CustomCapabilityMatcher extends DefaultCapabilityMatcher {
    @Override
    public boolean matches(Map<String, Object> nodeCapabilities, 
                           Map<String, Object> requestedCapabilities) {
        // Custom matching logic
        if (requestedCapabilities.containsKey("browserName")) {
            String browser = (String) requestedCapabilities.get("browserName");
            if (browser.equals("chrome-headless") && 
                nodeCapabilities.get("browserName").equals("chrome")) {
                // Allow headless Chrome to run on Chrome node
                return true;
            }
        }
        return super.matches(nodeCapabilities, requestedCapabilities);
