**4. Node Pool Management**

```java
public class NodePoolManager {
    private Map<String, NodePool> pools = new ConcurrentHashMap<>();
    private ExecutorService scaler = Executors.newSingleThreadExecutor();

    public class NodePool {
        private String name;
        private int minNodes;
        private int maxNodes;
        private int currentNodes;
        private Queue<Node> availableNodes = new ConcurrentLinkedQueue<>();
        private List<Node> allNodes = new CopyOnWriteArrayList<>();

        public void scaleUp(int count) {
            scaler.submit(() -> {
                for (int i = 0; i < count; i++) {
                    Node node = provisionNode();
                    allNodes.add(node);
                    availableNodes.offer(node);
                    currentNodes++;
                }
            });
        }

        public void scaleDown(int count) {
            for (int i = 0; i < count; i++) {
                Node node = availableNodes.poll();
                if (node != null) {
                    allNodes.remove(node);
                    deprovisionNode(node);
                    currentNodes--;
                }
            }
        }

        public Node borrowNode() {
            Node node = availableNodes.poll();
            if (node == null && currentNodes < maxNodes) {
                scaleUp(1);
                node = availableNodes.poll();
            }
            return node;
        }

        public void returnNode(Node node) {
            availableNodes.offer(node);
        }

        private Node provisionNode() {
            // Implementation for provisioning a new node
            return new Node();
        }

        private void deprovisionNode(Node node) {
            // Implementation for deprovisioning a node
        }
    }
}
