// Jenkins shared library
def splitTests(List tests, int nodeCount) {
    def chunks = []
    def testsPerNode = Math.ceil(tests.size() / nodeCount)

    for (int i = 0; i < nodeCount; i++) {
        def start = i * testsPerNode
        def end = Math.min(start + testsPerNode, tests.size())
        chunks.add(tests.subList(start, end))
    }
    return chunks
}

