                writer.write(String.format("<td><a href='%s'>View</a></td>\n", result.getScreenshot()));
                writer.write("</tr>\n");
            }

            writer.write("</table></body></html>");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
