**4. Test Retry Strategy**

```java
public class RetryAnalyzer implements IRetryAnalyzer {
    private int retryCount = 0;
    private static final int MAX_RETRY_COUNT = 2;
    private static final Set<String> flakyTests = new HashSet<>();

    @Override
    public boolean retry(ITestResult result) {
        if (retryCount < MAX_RETRY_COUNT) {
            // Don't retry certain failures
            if (isCriticalFailure(result)) {
                return false;
            }

            // Retry with backoff
            try {
                Thread.sleep(5000 * (retryCount + 1));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }

            retryCount++;

            // Track flaky tests
            if (retryCount == MAX_RETRY_COUNT) {
                flakyTests.add(result.getMethod().getMethodName());
            }

            return true;
        }
        return false;
    }

    private boolean isCriticalFailure(ITestResult result) {
        Throwable throwable = result.getThrowable();
        return throwable instanceof AssertionError ||
               throwable instanceof NullPointerException;
    }
}
