    private double calculateStabilityScore() {
        // Weighted calculation
        double passRateWeight = 0.5;
        double flakinessWeight = 0.3;
        double durationWeight = 0.2;

        double passRateScore = getAveragePassRate() * 100;
        double flakinessScore = 100 - (getFlakyTestPercentage() * 2);
        double durationScore = Math.min(100, 
            100 * (getTargetDuration() / getAverageDuration()));

        return (passRateScore * passRateWeight) +
               (flakinessScore * flakinessWeight) +
               (durationScore * durationWeight);
    }
}
