**3. Custom Wait Conditions**

```java
public class CustomWaitConditions {

    // Wait for element to have specific CSS property
    public static ExpectedCondition<Boolean> cssValueToBe(
            By locator, String property, String expectedValue) {
        return driver -> {
            WebElement element = driver.findElement(locator);
            String actualValue = element.getCssValue(property);
            return actualValue.equals(expectedValue);
        };
    }

    // Wait for page to finish loading
    public static ExpectedCondition<Boolean> pageLoaded() {
        return driver -> ((JavascriptExecutor) driver)
            .executeScript("return document.readyState")
            .equals("complete");
    }

    // Wait for AJAX calls to complete
    public static ExpectedCondition<Boolean> ajaxCompleted() {
        return driver -> {
            JavascriptExecutor js = (JavascriptExecutor) driver;
            return (Boolean) js.executeScript(
                "return jQuery.active == 0 && document.readyState == 'complete'");
        };
    }

    // Wait for element to stop moving (useful for animations)
    public static ExpectedCondition<Boolean> elementStabilized(By locator) {
        return new ExpectedCondition<Boolean>() {
            private Point lastLocation = null;
            private int stableCount = 0;
            private static final int REQUIRED_STABLE_CHECKS = 3;

            @Override
            public Boolean apply(WebDriver driver) {
                WebElement element = driver.findElement(locator);
                Point currentLocation = element.getLocation();

                if (lastLocation != null && lastLocation.equals(currentLocation)) {
                    stableCount++;
                    return stableCount >= REQUIRED_STABLE_CHECKS;
                }

                lastLocation = currentLocation;
                stableCount = 0;
                return false;
            }
        };
    }
}
