```java
public class BrowserCapabilitiesFactory {

    public static DesiredCapabilities getCapabilities(String browser) {
        switch(browser.toLowerCase()) {
            case "chrome":
                return getChromeCapabilities();
            case "firefox":
                return getFirefoxCapabilities();
            case "edge":
                return getEdgeCapabilities();
            case "safari":
                return getSafariCapabilities();
            default:
                throw new IllegalArgumentException("Unsupported browser: " + browser);
        }
    }

    private static DesiredCapabilities getChromeCapabilities() {
        ChromeOptions options = new ChromeOptions();

        // Common options
        options.addArguments("--start-maximized");
        options.addArguments("--disable-notifications");
        options.addArguments("--disable-popup-blocking");

        // Headless mode
        if (TestConfig.isHeadless()) {
            options.addArguments("--headless");
            options.addArguments("--window-size=1920,1080");
        }

        // Performance options
        options.addArguments("--disable-gpu");
        options.addArguments("--no-sandbox");
        options.addArguments("--disable-dev-shm-usage");

        // Experimental options
        options.setExperimentalOption("excludeSwitches", 
            Arrays.asList("enable-automation"));
        options.setExperimentalOption("useAutomationExtension", false);

        return options;
    }

    private static FirefoxOptions getFirefoxCapabilities() {
        FirefoxOptions options = new FirefoxOptions();

        FirefoxProfile profile = new FirefoxProfile();
        profile.setPreference("browser.download.folderList", 2);
        profile.setPreference("browser.download.manager.showWhenStarting", false);
        profile.setPreference("browser.helperApps.neverAsk.saveToDisk", 
            "application/pdf,application/octet-stream");

        options.setProfile(profile);
        options.setAcceptInsecureCerts(true);

        if (TestConfig.isHeadless()) {
            options.addArguments("--headless");
        }

        return options;
    }
}
